import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>JPG и PNG — два старейших формата изображений в вебе, и они решают противоположные задачи. JPG делает фото маленькими, а PNG сохраняет графику идеальной и прозрачной.</p>\n<p>Самое непонятое различие между ними — прозрачность. JPG вообще не может её хранить, а PNG может, но конвертация JPG в PNG волшебным образом её не создаёт.</p>\n<p>В этой статье два формата сравниваются честно, чтобы вы могли выбрать правильный для каждого изображения, с которым работаете.</p>\n<h2 id=\"jpg-at-a-glance\">JPG: краткий обзор</h2>\n<p>JPG — формат с потерями, созданный для фотографий. Он отбрасывает детали, которые ваши глаза едва замечают, что делает файлы фото значительно меньше любого формата без потерь.</p>\n<p>Типичное фото с телефона — 3 МБ как JPG и 15 МБ как PNG. Этот разрыв — причина, по которой каждая камера, телефон и сайт используют JPG для фото.</p>\n<p>JPG поддерживает только 8-битный цвет и не поддерживает прозрачность. Каждый пиксель имеет цвет, и такого понятия, как прозрачный пиксель JPG, не существует.</p>\n<p>Формат универсален. Каждое устройство, браузер, принтер и форма загрузки, построенные за последние тридцать лет, могут открыть JPG без дополнительного ПО.</p>\n<h2 id=\"png-at-a-glance\">PNG: краткий обзор</h2>\n<p>PNG — формат без потерь, созданный для графики. Он хранит каждый пиксель точно, что сохраняет резкие края, плоские цвета и текст идеально чёткими.</p>\n<p>PNG поддерживает прозрачность через альфа-канал. Каждый пиксель может быть полностью прозрачным, полностью непрозрачным или частично прозрачным, что позволяет делать мягкие края и тени.</p>\n<p>Цена — размер файла. Детальная фотография, хранящаяся как PNG, в несколько раз больше той же фотографии как JPG, потому что хранение без потерь не может отбросить текстуру.</p>\n<p>PNG тоже универсален, хотя и менее эффективен для фото. Каждый браузер, редактор и офисное приложение открывает файлы PNG без проблем.</p>\n<h2 id=\"what-transparency-is\">Что такое прозрачность на самом деле</h2>\n<p>Прозрачность означает, что части изображения пропускают фон. Логотип с прозрачным фоном чисто ложится на любой цвет, потому что вокруг него нет белого прямоугольника.</p>\n<p>Внутри файла прозрачность хранится как альфа-канал — дополнительный слой данных, говорящий, насколько прозрачен каждый пиксель. Значение ноль означает невидимость, а 255 — полную непрозрачность.</p>\n<p>Частичная прозрачность позволяет делать мягкие края. Тень плавно переходит от непрозрачной к невидимой, что выглядит естественно на любом фоне.</p>\n<p>У JPG вообще нет альфа-канала. Это структурный факт, а не настройка, и ни один файл JPG в мире не несёт прозрачности.</p>\n<h2 id=\"when-transparency-matters\">Когда прозрачность действительно важна</h2>\n<p>Логотипы — классический случай. Логотип компании должен лежать на белых страницах, цветных сайтах и тёмных слайдах, и только прозрачность позволяет одному файлу работать везде.</p>\n<p>Иконкам и стикерам она тоже нужна. Иконка приложения с белым прямоугольником вокруг выглядит сломанной, а прозрачная иконка сливается с любым интерфейсом.</p>\n<p>Вырезки товаров для интернет-магазинов зависят от неё. Фото товара с удалённым фоном чисто ложится на фон магазина, какого бы цвета он ни был.</p>\n<p>Наложения и водяные знаки используют частичную прозрачность. Полупрозрачный логотип поверх фото пропускает фото, сохраняя бренд видимым.</p>\n<h2 id=\"when-it-does-not-matter\">Когда прозрачность не имеет значения</h2>\n<p>Фотографиям прозрачность никогда не нужна. Фото — это прямоугольник пикселей без прозрачных частей, поэтому JPG справляется с ним идеально.</p>\n<p>Документам и сканам она тоже не нужна. Отсканированная страница — это полный прямоугольник, а белый фон правилен, а не проблема, которую нужно решать.</p>\n<p>Постам в соцсетях она редко нужна. Фото, опубликованное в Instagram или Facebook, заполняет свой кадр, и прозрачность всё равно была бы невидима.</p>\n<p>Если у изображения нет прозрачных частей, прозрачность не имеет значения. Выбирайте формат по размеру файла и резкости.</p>\n<h2 id=\"converting-cannot-add-transparency\">Почему конвертация не может добавить прозрачность</h2>\n<p>У JPG нет прозрачных пикселей, поэтому конвертация его в PNG даёт PNG тоже без прозрачных пикселей. Белый фон хранится как белые пиксели, а не как прозрачные.</p>\n<p>Единственный способ получить прозрачность — правильно удалить фон. Используйте инструмент удаления фона: он с помощью ИИ вырезает объект и сохраняет его как прозрачный PNG.</p>\n<p>Некоторые пытаются удалить белые пиксели в редакторе и назвать это прозрачностью. Это работает только для простых изображений и оставляет рваные края на всём детальном.</p>\n<p>Для чистого результата начните с PNG, у которого уже есть прозрачность, или удалите фон правильным инструментом. Одна конвертация никогда её не создаёт.</p>\n<h2 id=\"file-size-compared\">Размер файла: честное сравнение</h2>\n<p>Для фото JPG выигрывает с большим отрывом. Фото JPG на 3 МБ становится PNG на 12–18 МБ, без видимого улучшения, оправдывающего лишние байты.</p>\n<p>Для простой графики выигрывает PNG. Логотип с плоскими цветами и большими пустыми областями хорошо сжимается как PNG, иногда меньше, чем JPG того же изображения.</p>\n<p>Для скриншотов с текстом оба близки. PNG больше, но текст остаётся резким, а JPG размывает буквы, поэтому лишний размер покупает реальное качество.</p>\n<p>WebP превосходит оба для веба, предлагая прозрачность, как у PNG, при размерах, как у JPG. Это формат, который стоит выбрать, когда место назначения его поддерживает.</p>\n<h2 id=\"text-and-sharpness\">Резкость текста и штриховая графика</h2>\n<p>PNG сохраняет текст предельно резким, потому что хранит каждый пиксель точно. Скриншот, схема или график выглядят чисто в PNG при любом приближении.</p>\n<p>JPG размывает текст, потому что его сжатие группирует пиксели в блоки. Мелкие буквы получают ореолы и мягкие края, из-за чего их труднее читать.</p>\n<p>Штриховая графика, например диаграммы и технические чертежи, страдает в JPG так же. Тонкие линии размываются, а PNG сохраняет их чёткими.</p>\n<p>Для любого изображения, где текст или линии — это содержимое, правильный формат — PNG. Для любого изображения, где содержимое — фото, правилен JPG.</p>\n<h2 id=\"photos-compared\">Фотографии: JPG выигрывает, PNG проигрывает</h2>\n<p>У фото миллионы цветов, плавно переходящих друг в друга. JPG эффективно обрабатывает эти градиенты, а PNG должен хранить каждое тонкое изменение точно.</p>\n<p>В результате фото в PNG в несколько раз больше, но выглядит одинаково. Лишние байты не покупают ничего видимого, а более медленная загрузка — реальная цена.</p>\n<p>Редактирование — единственное исключение. Если вы планируете много раз редактировать фото, PNG останавливает накопление повреждений, а повторные сохранения JPG продолжают добавлять повреждения.</p>\n<p>Для доставки, однако, JPG или WebP всегда лучший выбор для фото. PNG — рабочий формат для фото, а не формат доставки.</p>\n<h2 id=\"choosing-for-web\">Выбор для веба</h2>\n<p>Для фото на сайте используйте JPG или WebP. Маленький размер файла ускоряет загрузку страниц, что важно и для посетителей, и для позиций в поиске.</p>\n<p>Для логотипов и иконок сайта используйте PNG или WebP. Прозрачность здесь важна, и оба формата её сохраняют, а WebP обычно даёт меньший файл.</p>\n<p>Для скриншотов на сайте используйте WebP или PNG. Текст должен оставаться читаемым, а JPG его размывает, поэтому вариант без потерь стоит лишних байтов.</p>\n<p>Современные сайты часто отдают WebP с запасным JPG или PNG. Такое сочетание даёт быструю загрузку современным браузерам и совместимость — старым.</p>\n<h2 id=\"choosing-for-print\">Выбор для печати</h2>\n<p>Для печатных фото JPG при высоком качестве подходит. Принтеры хорошо обрабатывают JPG, а размер файла управляем для больших печатных работ.</p>\n<p>Для печатных документов с текстом лучше PNG. Резкий текст чисто печатается, а текст JPG может выглядеть мягким на бумаге.</p>\n<p>Для печатных логотипов стандарт — PNG с прозрачностью. Логотип чисто ложится на любой цвет фона в печатном дизайне.</p>\n<p>Спросите типографию, что она предпочитает. Многие принимают оба формата, и их рабочий процесс может отдавать предпочтение одному из них по практическим причинам.</p>\n<h2 id=\"practical-rule\">Практичное правило, которое стоит запомнить</h2>\n<p>Задавайте два вопроса о каждом изображении. Есть ли у него прозрачность или резкий текст? И это фотография или графика?</p>\n<p>Прозрачность или резкий текст означает PNG. Фотография без этих нужд означает JPG. Графика для веба часто означает WebP, который справляется с обоими.</p>\n<p>Когда сомневаетесь, посмотрите на изображение. Если это фото человека или места, используйте JPG. Если это логотип, иконка или скриншот, используйте PNG.</p>\n<p>Это простое правило покрывает почти каждое изображение, с которым вы будете работать. Исключения редки и обычно касаются рабочих процессов редактирования, а не доставки.</p>\n<h2 id=\"logos-dark-backgrounds\">Логотипы на тёмном фоне</h2>\n<p>Логотипу на тёмном фоне нужна прозрачность, иначе он будет сидеть в видимом белом прямоугольнике. Логотип PNG с прозрачным фоном сливается с тёмным дизайном, а логотип JPG не может.</p>\n<p>Создавайте логотип как PNG с самого начала, когда он будет появляться на тёмном фоне. Прозрачная версия работает на тёмном, светлом и цветном фоне одинаково, одним файлом.</p>\n<p>Для сайта с тёмной темой проверьте логотип на фактическом цвете фона. Логотип, идеально выглядящий на белом, может исчезнуть на чёрном, если его цвета слишком тёмные.</p>\n<p>Для слайдов с тёмными шаблонами действует то же правило. Прозрачный логотип PNG чисто ложится на тёмный слайд, а логотипу JPG нужен белый прямоугольник, который ломает дизайн.</p>\n<p>Держите светлую и тёмную версии логотипа, если бренд использует обе. Белый логотип для тёмного фона и тёмный логотип для светлого фона покрывают каждую ситуацию.</p>\n<h2 id=\"icons-apps-websites\">Иконки для приложений и сайтов</h2>\n<p>Иконкам приложений нужна прозрачность: они лежат на домашних экранах с обоями позади. Иконка PNG с прозрачным фоном сливается с любыми обоями, а иконка JPG показывает прямоугольник.</p>\n<p>Фавиконы сайтов обычно в PNG или SVG. Фавикон PNG 32 на 32 пикселя резок во вкладке браузера, а маленький размер файла почти не имеет значения.</p>\n<p>Иконкам в интерфейсе нужны согласованные размеры. Набор иконок PNG при одинаковых размерах в пикселях выглядит единообразно, а смешанные размеры выглядят небрежно.</p>\n<p>Для современного сайта иконки WebP меньше иконок PNG с той же прозрачностью. Конвертируйте иконки PNG в WebP для живого сайта, а мастеров PNG держите для редактирования.</p>\n<p>Проверьте иконки на светлом и тёмном фоне перед выпуском. Иконка, зависящая от белого фона, исчезнет на тёмной теме, а исправление — прозрачная версия.</p>\n<h2 id=\"stickers-social-graphics\">Стикеры и графика для соцсетей</h2>\n<p>Стикеры по замыслу — прозрачные PNG. Стикер с белым прямоугольником вокруг выглядит сломанным в чате, а прозрачный стикер сливается с разговором.</p>\n<p>Графика в соцсетях с текстом нуждается в резкости PNG. Графическое объявление, сохранённое как PNG, читается чисто, а версия JPG смягчает буквы.</p>\n<p>Для графики, которой будут широко делиться, предоставьте оба формата. PNG для качества и JPG для совместимости покрывают каждую платформу и каждого получателя.</p>\n<p>Создавайте стикеры в высоком разрешении — не менее 512 на 512 пикселей. Маленький стикер, увеличенный, выглядит размытым, а большой, уменьшенный, остаётся резким.</p>\n<p>Проверьте размер файла перед загрузкой стикеров. Некоторые платформы ограничивают файлы стикеров несколькими сотнями килобайт, и большой PNG может сначала потребовать сжатия.</p>\n<h2 id=\"watermarks-overlays\">Водяные знаки и наложения</h2>\n<p>Водяной знак — это полупрозрачный логотип, размещённый поверх фото, и для работы ему нужна частичная прозрачность. PNG хранит значения альфа-канала, которые делают водяной знак прозрачным, а JPG не может.</p>\n<p>Размещайте водяной знак в углу, где он не скрывает объект. Водяной знак поверх лица раздражает зрителей, а знак в тихом углу защищает изображение незаметно.</p>\n<p>Держите водяной знак едва заметным — с непрозрачностью 30–50 процентов. Слабый водяной знак отпугивает воровство, не портя фото, а жирный отвлекает от самого изображения.</p>\n<p>Для партии фото применяйте водяной знак к мастерам PNG, а затем экспортируйте копии JPG для обмена. Мастера PNG сохраняют водяной знак редактируемым, а JPG — это формат доставки.</p>\n<p>Удаляйте водяной знак с изображений, которые вы продаёте или лицензируете. Покупатель ожидает чистый файл, а водяной знак принадлежит только превью и изображениям портфолио.</p>\n<h2 id=\"choosing-format-new-project\">Выбор формата для нового проекта</h2>\n<p>Начало нового проекта — лучшее время для осознанного выбора форматов. Чёткое правило с первого дня предотвращает папку смешанных форматов позже.</p>\n<p>Для сайта выберите WebP для фото и PNG для логотипов. Такое разделение даёт быструю загрузку и резкую графику, с прозрачностью там, где она важна.</p>\n<p>Для печатного проекта выберите PNG для графики и высококачественный JPG для фото. Типография принимает оба, а сочетание балансирует размер и резкость.</p>\n<p>Для кампании в соцсетях выберите JPG для фото и PNG для графики с текстом. Платформы всё равно всё сжимают, поэтому начало с правильного формата даёт лучший результат.</p>\n<p>Запишите правило форматов и поделитесь им с командой. Однострочное правило в заметках проекта предотвращает медленный дрейф в смешанные форматы, который преследует каждый проект.</p>\n<p>Проверяйте логотип на реальном фоне, а не на белом холсте редактора. Прозрачный PNG, идеальный на белом, на тёмном сайте может исчезнуть, а его края — показать ореолы.</p>\n<p>Держите две версии логотипа — светлую и тёмную. Один файл не может одинаково хорошо работать на белом и чёрном фоне, а две версии покрывают все случаи.</p>\n<p>Для веба конвертируйте мастер PNG в WebP. Прозрачность сохраняется, а файл становится заметно меньше, и страницы грузятся быстрее без потери резкости.</p>\n<p>Не полагайтесь на конвертацию для создания прозрачности. Если фон нужно убрать, сделайте это инструментом удаления фона до конвертации: потом будет поздно.</p>\n<p>Для иконок приложений проверяйте прозрачность на светлом и тёмном фоне. Иконка, которая зависит от белого фона, исчезнет на тёмной теме, а исправление — прозрачная версия. Тест на двух фонах занимает минуту и предотвращает досадные ошибки.</p>\n<p>Для стикеров и графики в соцсетях держите высокое разрешение исходника. Стикер 512 на 512 пикселей при уменьшении остаётся резким, а маленький стикер при увеличении размывается. Начинайте с большого файла и уменьшайте его, а не наоборот.</p>\n<p>Нужно конвертировать между этими двумя форматами? Используйте <a href=\"/ru/jpg-v-png/\">инструмент JPG в PNG</a> для рабочей копии без потерь или <a href=\"/ru/png-v-jpg/\">инструмент PNG в JPG</a>, чтобы уменьшить фото в PNG. Полные руководства читайте в статьях <a href=\"/ru/blog/jpg-v-png-polnoe-rukovodstvo/\">«JPG в PNG: полное руководство»</a> и <a href=\"/ru/blog/png-v-jpg-polnoe-rukovodstvo/\">«PNG в JPG: полное руководство»</a>, а шаги — в статье <a href=\"/ru/blog/kak-konvertirovat-jpg-v-png/\">«Как конвертировать JPG в PNG»</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Может ли у JPG быть прозрачный фон?","answer":"Нет. У JPG нет альфа-канала, поэтому каждый пиксель имеет сплошной цвет, и такого понятия, как прозрачный пиксель JPG, не существует. Если нужна прозрачность, используйте PNG или WebP. У логотипа в JPG всегда будет сплошной фон, обычно белый или чёрный."},{"question":"Сделает ли конвертация JPG в PNG белый фон прозрачным?","answer":"Нет. Белые пиксели — настоящие пиксели, и PNG хранит их как белые. Прозрачность нужно создавать, удаляя фон правильным инструментом, а не конвертируя форматы. Конвертация сохраняет изображение ровно таким, какое оно есть, включая его сплошной фон."},{"question":"Что лучше для логотипа на сайте — PNG или JPG?","answer":"PNG лучше, когда логотипу нужна прозрачность: он позволяет логотипу лежать на любом цвете фона. WebP ещё лучше, когда сайт его поддерживает, потому что сохраняет прозрачность при меньшем размере. JPG — неправильный выбор для логотипа, которому нужен прозрачный фон."},{"question":"Почему скриншоты выглядят лучше как PNG, чем как JPG?","answer":"Скриншоты полны резкого текста и тонких линий, которые сжатие JPG размывает. PNG хранит каждый пиксель точно, поэтому текст остаётся чётким. Файл PNG больше, но для скриншота читаемость стоит лишних байтов."},{"question":"Можно ли использовать PNG для всех изображений моего сайта?","answer":"Можно, но ваши страницы будут загружаться медленно. Фото в PNG в несколько раз больше фото в JPG без видимой пользы. Используйте PNG только для логотипов, иконок и скриншотов, а для фотографий — JPG или WebP. Такое разделение держит страницы быстрыми, а изображения — резкими."},{"question":"В каком формате сохранить прозрачный логотип для печати?","answer":"PNG с прозрачностью — стандарт для печатных логотипов: он сохраняет края резкими, а фон — прозрачным. Убедитесь, что PNG имеет высокое разрешение — не менее 300 DPI при печатном размере, чтобы логотип не выглядел мягким на бумаге."}];
